int emulate_sysenter(struct x86_emulate_ctxt *ctxt)
{
    uint64_t efer;
    struct {
        uint32_t cs;
        uint32_t eip;
        uint32_t esp;
    } sysenter_msr;

    if (ctxt_read_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEABLE;

    if ((efer & EFER_SCE) == 0)
        return X86EMUL_UNHANDLEABLE;

    if (ctxt->eflags & VM_MASK)
        return X86EMUL_EXCEPTION_GP(0);

    if (ctxt->mode == X86EMUL_MODE_REAL)
        return X86EMUL_EXCEPTION_GP(0);

    if (ctxt->mode == X86EMUL_MODE_PROTECTED && (ctxt->cs.ar & DESC_B_BIT) == 0)
        return X86EMUL_EXCEPTION_GP(0);

    if (ctxt_read_msr(ctxt, MSR_IA32_SYSENTER_CS, &sysenter_msr.cs))
        return X86EMUL_UNHANDLEABLE;

    if (ctxt_read_msr(ctxt, MSR_IA32_SYSENTER_EIP, &sysenter_msr.eip))
        return X86EMUL_UNHANDLEABLE;

    if (ctxt_read_msr(ctxt, MSR_IA32_SYSENTER_ESP, &sysenter_msr.esp))
        return X86EMUL_UNHANDLEABLE;

    if ((sysenter_msr.cs & 0xff00) != 0x8000)
        return X86EMUL_EXCEPTION_GP(0);

    if ((sysenter_msr.cs & 0x00ff) != 3)
        return X86EMUL_EXCEPTION_GP(0);

    ctxt->eip = sysenter_msr.eip;
    ctxt->regs[VCPU_REGS_RSP] = sysenter_msr.esp;
    ctxt->regs[VCPU_REGS_CS] = sysenter_msr.cs;
    ctxt->regs[VCPU_REGS_SS] = sysenter_msr.cs;

    return X86EMUL_CONTINUE;
}

int sysenter_emulation(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;
    uint32_t cs, eip, esp;
    int mode;

    // Get EFER MSR value
    if (ctxt->get_msr(ctxt, MSR_EFER, &efer) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    mode = (efer & EFER_SCE) ? (ctxt->mode == X86EMUL_MODE_PROT64 ? 3 : 1) : 0;

    switch (mode) {
        case 0: // Real mode or virtual 8086 mode
            return X86EMUL_EXCEPTION(GENERAL_PROTECTION);

        case 1: // Compatibility mode
            if (ctxt->get_segment(ctxt, &cs, &eip, NULL, NULL, NULL, VSeg_cs) != X86EMUL_CONTINUE)
                return X86EMUL_UNHANDLEABLE;

            if ((cs & 0xff00) != 0x0000)
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION);

            break;

        case 3: // 64-bit mode
            if (ctxt->mode != X86EMUL_MODE_PROT64)
                return X86EMUL_EXCEPTION(UNDEFINED_INSTRUCTION);

            if (ctxt->get_segment(ctxt, &cs, &eip, NULL, NULL, NULL, VSeg_cs) != X86EMUL_CONTINUE)
                return X86EMUL_UNHANDLEABLE;

            if ((cs & 0xfffffc00) != 0x00000000)
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION);

            break;

        default:
            return X86EMUL_EXCEPTION(UNDEFINED_INSTRUCTION);
    }

    // Get the necessary MSR values
    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    // Set up segment registers and instruction pointer
    if (ctxt->set_segment(ctxt, cs | 3, VSeg_cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;
    ctxt->regs[VCPU_REGS_RSP] = esp;

    return X86EMUL_CONTINUE;
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;
    struct {
        uint32_t cs;
        uint64_t eip;
        uint64_t esp;
    } sysenter_msrs;

    /* Read EFER MSR */
    if (ctxt->get_msr(ctxt, MSR_EFER, &efer)) {
        return X86EMUL_UNHANDLED;
    }

    /* Check if SYSENTER is enabled (SCE bit in EFER) */
    if (!(efer & EFER_SCE)) {
        return X86EMUL_UNHANDLED;
    }

    /* Read SYSENTER_CS, SYSENTER_EIP, SYSENTER_ESP */
    if (ctxt->get_msr(ctxt, MSR_SYSENTER_CS, &sysenter_msrs.cs)) {
        return X86EMUL_UNHANDLED;
    }
    if (ctxt->get_msr(ctxt, MSR_SYSENTER_EIP, &sysenter_msrs.eip)) {
        return X86EMUL_UNHANDLED;
    }
    if (ctxt->get_msr(ctxt, MSR_SYSENTER_ESP, &sysenter_msrs.esp)) {
        return X86EMUL_UNHANDLED;
    }

    /* Set up the CS selector and RPL */
    ctxt->regs->cs = sysenter_msrs.cs | 3;

    /* Set instruction pointer and stack pointer */
    ctxt->regs->ip = sysenter_msrs.eip;
    ctxt->regs->sp = sysenter_msrs.esp;

    /* Set CPL to 0 */
    ctxt->regs->cs &= ~0x3;

    return X86EMUL_CONTINUE;
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    unsigned long efer;
    unsigned long cs, eip, esp;
    int mode;

    if (ctxt->mode == X86EMUL_MODE_REAL)
        return X86EMUL_EXCEPTION(GENERAL_PROTECTION_FAULT, 0);

    efer = ctxt->get_msr(ctxt, MSR_EFER);

    mode = (efer & EFER_LMA) ? X86EMUL_MODE_PROTECTED : X86EMUL_MODE_COMPATIBILITY;
    if (mode == X86EMUL_MODE_COMPATIBILITY && (efer & EFER_SCE)) {
        cs = ctxt->get_segment(ctxt, X86_SEG_CS);
        eip = ctxt->get_msr(ctxt, MSR_LSTAR);
        esp = ctxt->get_msr(ctxt, MSR_STAR);
        ctxt->regs->cs = (cs & 0xffff) | 0x6000;
        ctxt->regs->ip = eip;
        ctxt->regs->sp = esp;
        return X86EMUL_CONTINUE;
    }

    return X86EMUL_EXCEPTION(UNDEFINED_INSTRUCTION_FAULT, 0);
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    u64 efer;
    int mode;
    int rc;

    rc = get_msr(ctxt, MSR_EFER, &efer);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    mode = get_mode(ctxt, efer);

    if (mode == X86EMUL_MODE_REAL) {
        return X86EMUL_UNHANDLEDMODE;
    } else if (mode == X86EMUL_MODE_PROT16 || mode == X86EMUL_MODE_PROT32) {
        u32 sysenter_cs;
        u64 sysenter_esp, sysenter_eip;

        rc = get_msr(ctxt, MSR_IA32_SYSENTER_CS, &sysenter_cs);
        if (rc != X86EMUL_CONTINUE)
            return rc;

        rc = get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &sysenter_esp);
        if (rc != X86EMUL_CONTINUE)
            return rc;

        rc = get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &sysenter_eip);
        if (rc != X86EMUL_CONTINUE)
            return rc;

        if (sysenter_cs & 0xff00) {
            return X86EMUL_UNHANDLEDMODE;
        }

        if ((sysenter_cs & 0x00ff) != 0) {
            return X86EMUL_CONTINUE;
        }

        if (mode == X86EMUL_MODE_PROT16) {
            if ((sysenter_cs & 0x000000ff) != 0x00000003)
                return X86EMUL_UNHANDLEDMODE;
        } else {
            if ((sysenter_cs & 0x000000ff) != 0)
                return X86EMUL_UNHANDLEDMODE;
        }

        ctxt->regs->eip = sysenter_eip;
        ctxt->regs->esp = sysenter_esp;
        ctxt->regs->cs = sysenter_cs;
        ctxt->regs->eflags &= ~(EF_VM | EF_IF);

        return X86EMUL_CONTINUE;
    } else {
        return X86EMUL_UNHANDLEDMODE;
    }
}
